const SUPPORT = 'suporte@txillapp.com';

const FAQ: { q: string; a: string }[] = [
  { q: 'O que são as vibes?', a: 'São a moeda do Txillapp e só servem dentro da app. Acumulas e usas para oferecer a quem segues (agradecer um bom post, retribuir um mimo, mandar «duas» ao teu bro), juntar no cofre de um TxillGroup e pagar nos locais que aceitam vibes. Nas apps da App Store e do Google Play não se compram: ganham-se e usam-se. Antes chamavam-se Txills: é a mesma moeda, com o mesmo valor.' },
  { q: 'Posso levantar as vibes ou trocá-las por dinheiro?', a: 'Não. As vibes nunca se levantam nem se trocam por dinheiro: só servem dentro do Txillapp. Os presentes vão inteiros para quem os recebe, sem comissão.' },
  { q: 'Como ganho vibes?', a: 'Ao criar a conta recebes 500 vibes de boas-vindas. Cada amigo que entra com o teu convite recebe 50 vibes quando a conta dele fica ativa (confirma o email, publica algo ou segue 3 pessoas e volta ao Txillapp noutro dia), e tu recebes 50 quando ele continua por cá mais 7 dias (até 5 por dia e 50 no total). Também podes recarregar em Definições, Vibes e pagamentos, «Pedidos e pagamentos».' },
  { q: 'Como faço uma chamada?', a: 'Abre a conversa com a pessoa e toca no telefone (voz) ou na câmara (vídeo), ou liga outra vez a partir de Chamadas. O teu email tem de estar confirmado. O som e a imagem vão cifrados de um telemóvel para o outro e o Txillapp não grava chamadas; fica só o registo na conversa e em Chamadas.' },
  { q: 'Como apago chamadas ou conversas?', a: 'Em Chamadas, segura uma chamada e escolhe «Apagar do registo» (tens uns segundos para «Desfazer»), ou toca em «Limpar» para apagar todas. Na lista de Mensagens, segura a conversa: abre uma folha com marcar como lida ou por ler, ver o perfil, ocultar e apagar a conversa (num TxillGroup, marcar como lido, info do grupo, ocultar e sair do grupo). No computador, passa o rato por cima da linha ou usa o botão direito. Apagar tira a conversa só da tua lista: do lado da outra pessoa fica. As chamadas com mais de 12 meses saem sozinhas.' },
  { q: 'Como oculto uma conversa?', a: 'Na lista de Mensagens, segura a conversa (no computador, botão direito ou ⋯) ou, dentro dela, toca em ⋯, e escolhe «Ocultar conversa». Dá nas conversas a dois e nos TxillGroups. Sai da tua lista e do número de mensagens por ler, e mensagens novas não a trazem de volta. Os avisos dessa conversa chegam discretos: só «Nova mensagem», sem nome, sem texto e sem som de destaque (no Android, no canal «Conversas ocultas»). A outra pessoa, ou os outros membros do grupo, não sabem. Ainda não há bloqueio com impressão digital ou PIN: quem tiver o teu telemóvel desbloqueado chega lá.' },
  { q: 'Onde ficam as conversas ocultas?', a: 'Em Mensagens, toca em ⋯ em cima e em «Conversas ocultas». Tocas numa para a abrir e conversar como sempre. Para a pôr de novo na lista, segura-a (ou abre o ⋯ dentro dela) e toca em «Mostrar outra vez». Sair de um TxillGroup também tira a marca. Guardamos só que a ocultaste e desde quando; entra na exportação dos teus dados e apaga-se com a conta.' },
  { q: 'Como ponho um coração numa mensagem?', a: 'Dá um duplo toque na mensagem (no computador, duplo clique): aparece um coração, a reação «Adorar», e quem está na conversa vê-a como as outras reações. Se já tinhas reagido, a tua reação passa a coração. Para a tirar ou escolher outra, segura a mensagem e usa as reações. Não dá nas mensagens de visualização única nem nas apagadas.' },
  { q: 'O que faz «Limpar conversa»?', a: 'Dentro da conversa (a dois ou num TxillGroup), toca em ⋯ e em «Limpar conversa», e confirma. As mensagens desaparecem só para ti: os outros continuam a vê-las e nada é apagado do servidor. As mensagens que estavam à espera de rede nessa conversa apagam-se e já não vão. A conversa fica na tua lista, vazia, até chegar outra mensagem. Não se desfaz. Para tirar a conversa da lista, apaga-a na lista de mensagens.' },
  { q: 'Como funcionam as mensagens temporárias?', a: 'Dentro da conversa, toca em ⋯ e em «Mensagens temporárias»: desligadas, 24 horas, 7 dias ou 90 dias. A dois, qualquer um dos dois muda, mas só quando já estão a conversar. Num TxillGroup, só os administradores. Vale para as mensagens enviadas a partir daí, e fica na conversa um aviso com o nome de quem mudou. Quando o tempo acaba, a mensagem desaparece para todos e é apagada dos servidores em poucos minutos, com a foto, o vídeo ou a voz. Quem a recebe pode guardá-la ou copiá-la antes. De um presente fica só o registo na carteira.' },
  { q: 'O que acontece se fizer uma captura de ecrã numa conversa?', a: 'Na app, no iPhone e no Android 14 ou mais recente, fica na conversa o aviso «Fulano fez uma captura de ecrã.» e a outra pessoa, ou os outros membros do TxillGroup, recebem uma notificação. A captura não é bloqueada e fica só no teu telemóvel. No Android mais antigo e no site não há deteção. Há no máximo um aviso a cada 30 segundos por conversa, e com as mensagens temporárias ligadas o aviso desaparece com elas. É uma ajuda, não uma garantia: há formas de copiar o ecrã que o telemóvel não deteta, como fotografá-lo com outra câmara.' },
  { q: 'Como apago uma mensagem?', a: 'Segura a mensagem e toca em Apagar. «Apagar para mim» tira-a só da tua conversa, em qualquer mensagem: os outros continuam a vê-la. «Apagar para todos» aparece nas tuas, a qualquer altura: apagamos o conteúdo e fica «Esta mensagem foi apagada». Quem recebeu pode já a ter lido. Funciona também nos TxillGroups.' },
  { q: 'Posso editar uma mensagem?', a: 'Sim, as tuas mensagens de texto, até 15 minutos depois de as enviares (não as de visualização única). Segura a mensagem e toca em Editar. Aparece «editada» ao lado da hora, os outros passam a ver só a versão nova e não guardamos a anterior. No mesmo menu, Copiar copia o texto.' },
  { q: 'Como envio um GIF?', a: 'Numa conversa, num TxillGroup ou nos comentários, toca nos stickers e escolhe o separador GIF. Procura ou escolhe um dos que estão em alta e toca para enviar. Os GIFs vêm do GIPHY: a pesquisa passa pelo servidor do Txillapp e o GIPHY não fica a saber quem és, mas as imagens vêm diretamente do GIPHY, que vê o endereço de rede de quem as vê. Guardamos só a ligação ao GIF, não a imagem. Abaixo dos 18 anos (ou sem data de nascimento na conta) só aparecem GIFs para todas as idades. Com «Reduzir movimento» ligado no telemóvel, os GIFs aparecem parados. «Apagar para todos» também apaga um GIF.' },
  { q: 'Posso colar uma imagem no chat?', a: 'No site, sim: cola (Ctrl+V ou Colar) ou arrasta uma imagem para a caixa de mensagem, numa conversa ou num TxillGroup. Abre-se uma pré-visualização e só é enviada quando tocas em Enviar; Cancelar deita-a fora. GIFs colados não dão: usa o separador GIF. Na app do telemóvel, usa o + para escolher a foto.' },
  { q: 'Posso enviar várias fotos e vídeos de uma vez?', a: 'Sim, numa conversa a dois ou num TxillGroup. Toca no ícone da galeria (numa conversa a dois, no + e em «Foto e vídeo») e escolhe até 10. Cada um vai numa mensagem à parte, pela ordem em que os tocaste, e o texto que estiver escrito na caixa vai como legenda do primeiro. Enquanto vão, aparece «A enviar 2 de 5…»; se algum falhar, os outros seguem e dizemos quantos não foram. Pela câmara é uma foto ou um vídeo de cada vez.' },
  { q: 'O que acontece se enviar uma mensagem sem rede?', a: 'Fica na conversa com um reloginho, à espera de rede, e vai sozinha quando a rede voltar, pela ordem em que as enviaste. Dá com texto, stickers, GIFs, voz, fotos e vídeos, a dois e nos TxillGroups. A app tenta enquanto está aberta e à frente (em segundo plano não gasta bateria nem dados), também depois de a fechares e voltares a abrir. Até lá, a mensagem e o ficheiro ficam guardados só no teu aparelho; um ficheiro com mais de 25 MB pergunta antes se o queres guardar. Se já não a quiseres enviar, segura-a e toca em Apagar. «Não enviada» só aparece se o Txillapp a recusar (por exemplo, já não podes enviar mensagens nessa conversa): toca em «Tentar outra vez» ou em «Apagar». Sem rede, a app abre com a conta da última vez e, em Mensagens, mostra em «Por enviar» as conversas com mensagens à espera. «Limpar conversa» e terminar sessão apagam as que estavam à espera, e essas já não vão.' },
  { q: 'Uso o Txillapp em mais de um aparelho. As conversas ficam iguais?', a: 'Sim. O que envias, editas, apagas ou lês num aparelho aparece logo nos outros onde tens a sessão iniciada, sem som nem aviso.' },
  { q: 'Como envio a minha localização?', a: 'Na conversa, toca no + e em Localização. Escolhe a tua localização atual (vês a precisão), arrasta o mapa até ao ponto que queres, ou escolhe um sítio em «Sítios perto» ou na pesquisa. Nada é enviado sem tocares em Enviar. A mensagem leva o ponto exato (e, num sítio, o nome e a morada), que quem está na conversa vê. Num TxillGroup, todos os membros veem, também os que entrarem depois.' },
  { q: 'Como funciona a localização em direto?', a: 'Só nas conversas a dois. Em Localização, toca em «Partilhar localização em direto», escolhe 15 minutos, 1 hora ou 8 horas e confirma. A posição atualiza-se mais ou menos de 20 em 20 segundos enquanto o Txillapp está aberto: em segundo plano ou com a app fechada, não. Toca em Parar na mensagem para acabar antes do tempo. No fim, a mensagem fica só «Partilha em direto terminada», sem mapa.' },
  { q: 'Posso esconder o meu IP nas chamadas?', a: 'Sim. Em Definições, Mensagens e chamadas, «Esconder o meu IP nas chamadas» (aparece quando o servidor de chamadas está ligado). A chamada passa sempre pelo servidor do Txillapp e quem está do outro lado não vê o teu endereço. Pode ficar um pouco mais lenta.' },
  { q: 'O que é uma Txillada?', a: 'É vídeo ao vivo no Txillapp. Em Criar, escolhe «Txillada», escreve um título se quiseres, escolhe o tipo (Pública: quem pode ver o teu perfil; Para amigos: quem segues e te segue, ou só os teus amigos próximos, a mesma lista dos mimos; Privada: quem quiser entrar paga uma entrada em vibes) e toca em «Começar Txillada». O tipo não muda depois de começar. Só abre quem tem 18 anos ou mais, pela data de nascimento da conta, e o email confirmado. Quem te pode ver vê a roda vermelha «AO VIVO» na tua foto e entra com um toque, e quem está a ver comenta, reage e brinda. Uma ligação de uma Txillada abre dentro da app, em ecrã inteiro, também a partir de uma conversa. Quem tem um bloqueio contigo nunca a vê. Dura no máximo 4 horas.' },
  { q: 'Como reajo numa Txillada?', a: 'Toca numa das reações da barra: Olá (a mão), o brinde (os copos), o fogo, o riso ou o coração. Sobem pelo ecrã de quem está na sala, com o teu nome, e o olá aparece num balão «@tu: Olá». O brinde conta como brinde. Quem transmite não brinda, mas manda o fogo, o riso, o coração e «Olá a todos», e responde com um olá a quem entrou. As reações não se guardam: só passam ao vivo. Há um limite: 8 reações por segundo e um olá a cada 4 segundos. Para brindar um comentário, toca no brinde ao lado dele, dá dois toques no comentário ou no balão, ou escolhe «Brindar» no menu do comentário (uma vez por comentário): quem está na sala vê a contagem, sem saber quem brindou, e quem escreveu não recebe aviso. Um toque (ou um toque longo) num comentário, ou no comentário fixado em baixo, abre o menu: «Responder a @fulano» (o teu comentário começa pelo @ da pessoa), «Brindar» e «Denunciar comentário». No teu comentário, o menu tem «Apagar».' },
  { q: 'Como funciona uma Txillada privada?', a: 'Quem pode ver o teu perfil vê que estás ao vivo, com um cadeado e o preço, mas não vê nada da sala (nem o vídeo, nem os comentários, nem quem está a ver) até pagar. A entrada vai de 5 a 5000 vibes e paga-se uma vez, com as vibes da carteira: se a pessoa sair, volta a entrar sem pagar outra vez. Tu e quem convidares para transmitir entram sem pagar. Numa privada, quem está a ver não aparece aos outros: só tu vês a lista e os «entrou». Se a moderação cortar a Txillada, as entradas voltam para a carteira de quem pagou; se a terminares tu, não há devolução. As vibes ficam na app: não se levantam.' },
  { q: 'O que é a Angariação numa Txillada?', a: 'Ao preparar a Txillada, liga «Angariação», escreve uma meta em vibes e, se quiseres, para quê (até 80 letras). Quem está a ver toca em «Oferecer», ao lado do comentário (ou em «Ajudar», na meta), e escolhe 5, 10, 50 ou 100 vibes: um toque no valor oferece logo, e a folha fica aberta para dar mais. Também há «Outro valor» (até 5000 de cada vez). As vibes saem da carteira. Cada oferta aparece na conversa, destacada («@fulano ofereceu 50 vibes»), a barra «X de Y vibes» sobe para todos na sala e ficam à vista os três que mais ofereceram. Também se oferece numa Txillada sem meta. As ofertas vão logo para a carteira de quem transmite e não se devolvem; ficam no histórico da carteira e em «Descarregar os meus dados», também depois de a Txillada acabar.' },
  { q: 'Os outros veem que estou a ver uma Txillada?', a: 'Sim, menos numa Txillada privada (aí só quem transmite te vê na lista). Quem transmite e quem está a ver veem a tua foto, o teu nome e o teu @ nas caras ao lado do contador e na lista «A ver agora» (toca nas caras para a abrir), e recebem «@tu entrou» quando entras. Tu também vês quem lá está. Quem tem um bloqueio contigo não te vê, e tu não o vês. Se passares a transmitir como convidado, sais de «A ver agora» e todos na sala te veem e ouvem no ecrã. Com o leitor pequeno aberto, fora do ecrã da Txillada, continuas na sala e na lista. Se não queres que saibam, não entres.' },
  { q: 'Como entro numa Txillada a transmitir?', a: 'Numa Txillada que estás a ver, toca em «Pedir para entrar». O anfitrião vê o pedido e aceita ou recusa; também te pode convidar, mesmo antes de entrares (recebes um aviso que abre a Txillada; numa privada, entras sem pagar), e aí aceitas ou recusas. Precisas de ter 18 anos ou mais pela data de nascimento da conta. Ao aceitar, a tua câmara e o teu microfone passam a transmitir para todos na sala, ao lado do anfitrião (até 3 convidados). Para parar, toca em «Desligar a câmara e ficar a ver» ou em «Sair do ecrã»: deixas de transmitir e continuas a ver, a comentar e a oferecer. O anfitrião também te pode tirar do ecrã. Nada fica gravado, e o pedido ou o convite apaga-se 7 dias depois do fim.' },
  { q: 'Como convido alguém para a minha Txillada?', a: 'Toca no botão das pessoas e escreve o @ em «Convidar por @» (aparecem sugestões, com o selo de quem é verificado), ou abre a lista «A ver agora», toca na pessoa e escolhe «Convidar para transmitir». Pelo @ convidas também quem ainda não entrou: recebe um aviso que abre a Txillada (numa privada, entra sem pagar). Só dá para quem pode ver a tua Txillada e tem 18 anos ou mais, e não para quem tem um bloqueio contigo. Os pedidos para entrar chegam ao botão das pessoas, com o número à espera: lá aceitas, recusas, retiras um convite ou tiras quem está a transmitir. Cabem até 3 convidados ao mesmo tempo, e cada um pode sair quando quiser.' },
  { q: 'A Txillada fica gravada?', a: 'Não. O vídeo só passa ao vivo pelo servidor de vídeo do Txillapp: não há gravação, repetição nem cópia, e quando acaba já ninguém a vê. As reações, os olás e os «entrou» não se guardam. Os comentários, os brindes e os brindes aos comentários apagam-se 7 dias depois do fim (um comentário denunciado fica até a moderação decidir). Fica o registo (o título, o tipo, as horas e os números) até eliminares a conta, e entra em «Descarregar os meus dados». As entradas pagas e as ofertas de vibes não se apagam: ficam no histórico da carteira, como os presentes. Quem está a ver pode, mesmo assim, gravar o ecrã ou filmá-lo com outro aparelho.' },
  { q: 'Como modero a minha Txillada?', a: 'Toca num comentário (ou segura-o) para abrir o menu. Lá respondes, brindas, fixas o comentário, apagas ou expulsas a pessoa: sai logo e não volta a entrar nessa Txillada. O comentário fixado fica à vista de todos em baixo até o tirares («Tirar o fixado» no menu) ou o comentário sair (apagado, removido pela moderação ou com a conta de quem o escreveu). Só há um fixado de cada vez: fixar outro troca. Quem tem um bloqueio com quem o escreveu, ou o denunciou, não o vê. Na lista «A ver agora», toca numa pessoa para lhe dizer olá ou a tirar da Txillada. Quem pode comentar segue a tua escolha em Definições, Privacidade, «Quem pode comentar». Para comentar é preciso o email confirmado, cada pessoa comenta no máximo uma vez a cada 2 segundos e os comentários passam pelo filtro de palavras. Para acabar, toca em «Terminar».' },
  { q: 'O que não posso transmitir numa Txillada?', a: 'Valem as regras da malta: nada de nudez nem conteúdo sexual, violência, ódio, assédio, atividades perigosas ou ilegais, nem nada que exponha ou ponha em perigo um menor. Não transmitas quem não aceitou aparecer, nem música, filmes, jogos ou programas de outras pessoas sem autorização, também a música de fundo. A moderação pode cortar uma Txillada ao vivo e a conta pode ser suspensa.' },
  { q: 'Como denuncio uma Txillada ou um comentário dela?', a: 'Na Txillada, toca em ⋯ e em «Denunciar a Txillada». A moderação pode cortá-la ao vivo, e quem transmitia recebe um aviso com o motivo. Para denunciar um comentário, toca nele e escolhe «Denunciar comentário»: deixa logo de te aparecer (também se estiver fixado), continuas na sala e o comentário fica guardado até a moderação decidir. Se for removido, sai para todos e quem o escreveu recebe um aviso com o motivo. A pessoa não sabe que foste tu. Para deixares de ver a pessoa, bloqueia-a.' },
  { q: 'Como deixo de receber avisos das Txilladas?', a: 'Em Definições, Notificações, desliga «Txilladas». O aviso diz «@fulano abriu uma Txillada», com o título se tiver um, e chega no máximo uma vez por hora por pessoa. No telemóvel, o título lê-se no ecrã de bloqueio. Do mesmo tipo são o «reabriu a Txillada», o convite para transmitir, o convite de uma menção e os avisos das Txilladas agendadas (quando começa uma que pediste para lembrar, quando a cancelam ou mudam de hora, e os das tuas, 15 minutos antes e na hora).' },
  { q: 'Se sair do ecrã da Txillada, ela desliga?', a: 'Não. Se fores a um perfil, à carteira, a uma notificação ou usares o voltar do Android, a Txillada continua. A ver, fica um leitor pequeno com o vídeo e o som, que arrastas para um lado: um toque volta à Txillada e o X sai. A transmitir, continuas ao vivo, com a câmara e o microfone, e aparece «Estás ao vivo · Voltar» por cima dos separadores. Só Sair, o X, Terminar, Concluir no resumo ou sair da conta desligam. No site, se a página recarregar, aparece «Estavas na Txillada de @fulano · Voltar» durante 30 minutos, enquanto ela decorrer.' },
  { q: 'Como leio os comentários de antes numa Txillada?', a: 'Toca ou arrasta na zona dos comentários: abre-se a lista com todos desde que entraste, e ao chegar ao topo carregam os anteriores. Enquanto lês para trás, os novos não te puxam para baixo: toca em «N comentários novos» para voltares ao fim. Um toque num comentário abre o menu dele.' },
  { q: 'Como menciono alguém numa Txillada?', a: 'No comentário, escreve @: aparecem logo pessoas, primeiro o anfitrião, quem transmite, quem está a ver e quem comentou (numa privada, quem está a ver só aparece ao anfitrião). Quem não está a ver tem «Convida-se ao mencionar»: ao enviares, recebe «mencionou-te na Txillada… vem ver» e tu vês «Convidaste @fulano para vir ver a Txillada». Cada pessoa recebe no máximo um destes convites por Txillada a cada 10 minutos, e só se pode ver a Txillada e não tem um bloqueio contigo nem com o anfitrião. Numa privada, a pessoa paga a entrada como as outras. Quem já está a ver recebe só o aviso da menção, na sala. Só mencionas quem aceita menções tuas (Definições, Privacidade, «Quem pode mencionar-me»).' },
  { q: 'Posso desligar a câmara numa Txillada?', a: 'Sim. Se és o anfitrião, desliga a câmara e liga-a outra vez quando quiseres: continuas ao vivo com o som, e quem vê tem a tua foto e «Câmara desligada». Se transmites como convidado, toca em «Desligar a câmara e ficar a ver»: deixas de transmitir e continuas na Txillada a ver.' },
  { q: 'Posso reabrir uma Angariação que terminei?', a: 'Sim, se a terminaste antes de chegar à meta. No resumo, toca em «Reabrir a Angariação» (diz quantas vibes faltam). Dá até 24 horas depois do fim e no máximo 3 vezes. É a mesma Txillada: a meta, o que já se juntou, quem ofereceu e os comentários de antes ficam, e o tempo começa do zero. Numa privada, quem já pagou entra sem pagar outra vez. Avisamos quem ofereceu e quem pagou e, no máximo uma vez por hora, quem te segue. Não dá numa Txillada cortada pela moderação, numa que já chegou à meta ou com outra a decorrer: aí abre uma nova.' },
  { q: 'Como agendo uma Txillada?', a: 'Em Criar, escolhe «Txillada», prepara-a como de costume (o título, o tipo e, se quiseres, o preço da entrada ou a Angariação) e toca em «Agendar», ao lado de «Começar». Escolhe o dia (Hoje, Amanhã, os dias seguintes ou «Outro dia», no calendário) e a hora, de 15 em 15 minutos: pelo menos 15 minutos à frente e no máximo daqui a 30 dias. Tens até 5 agendadas, a pelo menos 30 minutos umas das outras. Aparece no teu perfil, na fila «Em breve» de quem te segue e na ligação que partilhas, só a quem poderia ver uma Txillada desse tipo. No cartão vês quantas pessoas pediram para ser lembradas (não quem), mudas o título, o dia e a hora em «Editar» (o tipo, o preço e a meta não mudam) e cancelas em «Cancelar a Txillada»: quem pediu lembrete é avisado. Recebes um aviso 15 minutos antes e outro na hora. «Começar» fica ativo 1 hora antes; antes disso, «Começar agora» passa a hora para agora. Se não começares até 2 horas depois da hora marcada, deixa de valer.' },
  { q: 'Como sou lembrado de uma Txillada?', a: 'Numa Txillada agendada (no perfil de quem a marcou, na fila «Em breve» do Início ou numa ligação), toca em «Lembrar-me»: passa a «Vais ser lembrado». Quando começar, recebes «@fulano começou a Txillada que pediste para lembrar». Se for cancelada ou mudar de hora, também te avisamos. Para deixares de ser lembrado, toca outra vez no botão. O anfitrião vê quantas pessoas pediram, nunca quem. Estes avisos são do tipo «Txilladas»: com ele desligado em Definições, Notificações, não recebes nenhum. Numa Txillada privada, a entrada paga-se só para entrar, quando estiver a decorrer.' },
  { q: 'O que é o Mixar?', a: 'Um feed só teu e de outra pessoa. Juntam os gostos e recebem todos os dias, a partir das 05:00, até 24 publicações (sobretudo tchekas) escolhidas para os dois, só com o que os dois podem ver. Cada item diz se veio pelos teus gostos, pelos da outra pessoa ou pelos dos dois. Reagem com as reações do Mixar (só os dois as veem e o autor não é avisado), conversam sobre cada vídeo, guardam os que gostam nos Guardados dos dois e jogam o Mixa Challenge: um desafio por dia, em que cada um escolhe às escondidas e o resultado só abre quando os dois escolheram. O que fazem lá dentro afina a seleção seguinte. Para mandar um item para a vossa conversa, toca nos três pontos (⋯) do item, por baixo de «Conversa» e «Guardar», e em «Mandar a…». Encontras o Mixar com uma pessoa no ícone do Mixar, em cima, na conversa com ela; nas Mensagens, a linha do Mixar aparece por cima da lista quando há novidades; e todos os teus Mixar estão em Definições, Mensagens e chamadas, «Os meus Mixar».' },
  { q: 'Como convido alguém para um Mixar?', a: 'Na conversa com a pessoa, toca em ⋯ e em «Mixar com…», ou no + e em «Mixar». O convite vai como um cartão na conversa. Só convidas quem te pode enviar mensagens (as mesmas regras das conversas, com bloqueios e «Quem pode enviar-me mensagens»). Há limites: até 20 Mixar ativos, 10 convites por dia e 3 à mesma pessoa em 24 horas. Se a pessoa tocar em «Agora não», não és avisado: o cartão diz só que o convite já não está ativo.' },
  { q: 'O que a outra pessoa vê de mim no Mixar?', a: 'A percentagem de afinidade, os temas em comum e os que são mais teus (temas como futebol ou música, nunca as publicações que brindaste, comentaste ou guardaste), a tua reação em cada item, se já viste cada item (nunca quanto tempo) e, no desafio, só que já escolheste, até os dois escolherem. Depois disso, cada um vê a escolha do outro. Vê também os teus comentários na conversa de cada item, o que guardaste à mão nos Guardados, os temas que tiraste do Mixar e, enquanto tens o Mixar aberto, que estás lá e em que vídeo. Nunca vê o teu «Menos disto» nem os teus temas privados.' },
  { q: 'Como saio de um Mixar?', a: 'Abre o Mixar, toca no nome em cima e em «Sair do Mixar». Acaba para os dois, sem notificação, e o cartão na conversa diz que terminou. Um convite que mandaste e ainda está à espera cancela-se em «Cancelar convite». O que lá fizeram (também a conversa de cada item e os Guardados) apaga-se de vez 30 dias depois. Um bloqueio também termina o Mixar. No Mixar do grupo é diferente: vê «Como saio do Mixar do grupo?».' },
  { q: 'Que avisos manda o Mixar?', a: 'O convite e o «aceitou o vosso Mixar»; a seleção do dia, no máximo uma vez por dia em cada Mixar, só entre as 08:00 e as 21:00 e só se ainda não o abriste nesse dia; no Mixa Challenge, quando a outra pessoa já escolheu e falta a tua escolha; e o resultado, para quem escolheu primeiro. As reações e os comentários não mandam aviso. No Mixar do grupo, também «propôs um Mixar do grupo». Desligas todos em Definições, Notificações, «Mixar» (já não vão com os de Mensagens). Abrir o Mixar dá os avisos dele por lidos. O registo dos avisos que te mandámos apaga-se ao fim de 30 dias.' },
  { q: 'Quem aparece em «Faz um Mixar com…»?', a: 'Na lista dos teus Mixar sugerimos até 3 pessoas: com quem trocaste muitas mensagens nos últimos 30 dias (pelo menos 10, 3 de cada lado), que segues e te seguem, a quem podes enviar mensagens e com gostos parecidos (afinidade de 40% ou mais). Contamos as mensagens, nunca as lemos. A pessoa não é avisada. Toca em «Convidar» para mandar o convite ou em «Agora não» para a esconder durante 30 dias. Os teus temas privados não contam.' },
  { q: 'Como converso sobre um vídeo do Mixar?', a: 'No item, toca em «Conversa» (o balão, ao lado). Só tu e a outra pessoa veem estes comentários, até 500 caracteres cada, e é preciso ter o email confirmado. Valem as regras da malta. Apagas os teus em «Apagar» e deixam de se ver para os dois. Se um comentário da outra pessoa não estiver bem, toca em «Denunciar»: sai logo da tua vista e a moderação decide.' },
  { q: 'O que quer dizer «está a ver contigo»?', a: 'Que a outra pessoa tem o Mixar aberto agora. Aparece por baixo do cabeçalho, com «No mesmo vídeo que tu» ou «Noutro vídeo» (toca para ires lá), e «está aqui» no vídeo em que ela está. As reações dela aparecem na hora. Ela vê o mesmo de ti, também com «Mostrar quando estou online» desligado. Desaparece pouco depois de um dos dois sair.' },
  { q: 'O que faz «Mais 5» no Mixar?', a: 'No fim da seleção do dia, «Mais 5» junta até 5 publicações novas, escolhidas da mesma forma e sem repetir nada que já saiu nesse Mixar. Dá para pedir 3 vezes por dia em cada Mixar, a contar com os pedidos dos dois. A seleção nova chega às 05:00.' },
  { q: 'O que são os Guardados do Mixar?', a: 'A coleção dos dois. Uma publicação entra sozinha quando os dois reagem a ela (sem ser com nah), ou quando um de vocês toca em «Guardar» no item. Vês tudo no botão «Guardados», em cima no Mixar, com quem guardou cada uma. Qualquer um dos dois tira uma publicação (toca outra vez em «Guardado»), e aí só volta se alguém a guardar à mão.' },
  { q: 'Como vejo menos de um tema no Mixar?', a: 'No item, toca nos três pontos (⋯) por baixo de «Conversa» e «Guardar» e em «Menos disto»: esse tema e esse autor passam a pesar menos no vosso Mixar, sem a outra pessoa saber. Para tirar o tema de vez, escolhe «Não quero «Futebol» no nosso Mixar» (com o tema do item): sai da seleção dos dois, logo também da de hoje, e a outra pessoa vê que foi tirado. Para voltar atrás, toca no nome do Mixar, em cima, e em «Afinar os temas do Mixar». O teu feed normal não muda.' },
  { q: 'O que são os Temas privados do Mixar e onde estão?', a: 'São temas que nunca aparecem nos teus Mixar: não contam para a afinidade nem para as sugestões, não entram nos temas em comum, nas razões dos itens («Porque gostas de…») nem no resumo da semana. Valem para todos os teus Mixar e ninguém sabe quais são. Escolhes em Definições, Privacidade, «Temas privados no Mixar», ou no Mixar, a tocar no nome em cima e em «Temas privados».' },
  { q: 'O que é o resumo da semana do Mixar?', a: 'Os vossos últimos 7 dias: o que mais vos fez reagir, os acertos no Mixa Challenge, a série, os vídeos vistos e os temas da semana. Abre-se no calendário, em cima no Mixar, e à segunda-feira aparece no fim da seleção. Podes partilhá-lo como imagem no Zás ou nos mimos: a imagem leva o primeiro nome dos dois, a série, os acertos, os vídeos vistos e os temas, nunca o vídeo nem os temas privados. Qualquer um dos dois pode partilhar, por isso combina com a outra pessoa. No Mixar do grupo ainda não há resumo da semana.' },
  { q: 'O que é o Mixar do grupo?', a: 'O Mixar de um TxillGroup com 3 a 5 pessoas. No grupo, toca em «Mixar do grupo», no cabeçalho ou no ⋯, para o propor: entras logo e os outros recebem «propôs um Mixar do grupo», com «Entrar» e «Agora não». Começa quando 3 entraram, contigo, e cabem até 5. Só quem entra vê o feed, a conversa, os Guardados e o desafio, e só os gostos de quem entrou contam. A seleção só tem o que todos podem ver, e cada item diz de quem é o gosto («do gosto de Ana e Zeca», «do gosto de todos»). As reações, os vistos e a conversa de cada item são só entre quem está. Uma publicação vai sozinha para os Guardados quando a maioria reage (no mínimo 2). No Mixa Challenge vês quem já escolheu e, no fim, quantos escolheram cada opção, sem saber quem escolheu o quê. «Mandar» um item põe-no na conversa do grupo. Ainda não há o resumo da semana nem o «está a ver contigo». Os Mixar dos teus grupos estão também em «Os meus Mixar».' },
  { q: 'Disse «Agora não» ao Mixar do grupo. Posso entrar depois?', a: 'Sim. Enquanto o Mixar durar e houver lugar (até 5), abre-o no grupo ou em «Os meus Mixar» e toca em «Entrar». Até lá não vês o feed nem os gostos dos outros, e os teus não contam: vês só quem já entrou e quantos faltam.' },
  { q: 'Como saio do Mixar do grupo?', a: 'Abre o Mixar, toca no nome em cima e em «Sair do Mixar do grupo». Continuas no grupo e podes voltar a entrar. Sair do grupo, ser tirado por um administrador ou eliminar a conta também te tira do Mixar do grupo. Com menos de 3 pessoas, o Mixar acaba para todos e apaga-se de vez 30 dias depois; apagar o grupo apaga-o logo.' },
  { q: 'O que é o SuperTxill?', a: 'É a inteligência artificial do Txillapp. Abres no botão do SuperTxill nas Mensagens ou na Pesquisa. Na «Conversa» perguntas onde anda a malta, que sítios e eventos há perto, se há Txilladas a decorrer, pedes ideias para um plano ou uma legenda; em «Malta para ti» vês pessoas com gostos parecidos com os teus. É grátis, com um limite de respostas por dia (e um total por mês para toda a app). Uma resposta pode demorar dezenas de segundos: enquanto isso aparece «está a pensar…», e podes fechar o ecrã e ver a resposta quando voltares.' },
  { q: 'Que dados usa o SuperTxill?', a: 'Só dados da app que tu já podes ver, e só quando a pergunta precisa: a malta no «À tua volta» (quem aceitou aparecer no mapa e te deixa vê-la, com a distância e o sítio aproximados, nunca coordenadas), os locais e os eventos perto e os check-ins de hoje, as Txilladas a decorrer que podes ver, a tua geleira e a da malta que ta deixa ver, a «Malta para ti», o teu primeiro nome e a hora. Para saber onde estás, usa a última posição que partilhaste no «À tua volta» (até 3 horas) ou a cidade do teu perfil; nunca pede o GPS. O que consulta não se guarda à parte. Não lê as tuas conversas, nem as mensagens ou as vibes de ninguém.' },
  { q: 'Para onde vão as conversas com o SuperTxill?', a: 'Não saem do Txillapp. O SuperTxill responde com um modelo aberto (Qwen3) que corre no nosso servidor: as conversas não vão para outras empresas e não servem para treinar modelos. Ficam na tua conta as últimas 60 mensagens, só para ti. Para as apagar, na «Conversa» toca no caixote do lixo («Apagar a conversa»); também se apagam quando eliminas a conta.' },
  { q: 'O SuperTxill pode errar?', a: 'Pode. É uma IA: confirma o que for importante (horários, preços, moradas) e não o uses para decisões médicas, jurídicas ou financeiras. Não faz nada na app por ti: não segue, não envia nem compra, diz-te onde o fazes. E não ajuda a localizar ou seguir ninguém às escondidas.' },
  { q: 'O que é um TxillGroup?', a: 'Um grupo para combinar a saída com a malta: viagem, festa ou fim de semana. Tem o plano (onde, quando e quem vai), sondagens, a lista do que levar, despesas para saber quem deve a quem, um álbum e um cofre de vibes. Cabem até 50 pessoas. A conversa e o resto só os veem os membros.' },
  { q: 'Quem vê o meu TxillGroup?', a: 'Depende do modo, que um administrador escolhe nos detalhes do grupo, em «Quem vê e quem entra». Privado (de origem): ninguém de fora o vê e só entra quem um administrador adiciona. Privado, visível no mapa: aparece em À tua volta com o nome, a capa, a foto, o tipo, a descrição, o plano e o número de membros, e quem quiser entrar pede. Público: aparece no mapa e qualquer pessoa entra logo. Atenção: quem entra vê o que já foi partilhado no grupo, incluindo mensagens, fotos e despesas antigas.' },
  { q: 'Onde aparece o grupo no mapa?', a: 'No sítio do grupo: um local do Txillapp que esteja no mapa, ou um ponto que um administrador marca no mapa, com um nome se quiser. O ponto marcado fica guardado só aproximado (cerca de 1,5 km), nunca o sítio exato. Nunca aparece onde estão os membros. Depois das datas do plano, o grupo sai do mapa.' },
  { q: 'Como entro num TxillGroup que vi no mapa?', a: 'Abre o grupo e toca em «Entrar no grupo» (grupo público) ou «Pedir para entrar» (grupo privado, visível no mapa). Os administradores veem o teu nome, o @ e a foto. Se aceitarem, recebes uma notificação; se recusarem, não és avisado. Podes cancelar o pedido enquanto espera. Se tens um bloqueio com alguém do grupo, o grupo não te aparece.' },
  { q: 'Como faço alguém administrador do grupo?', a: 'Nos detalhes do grupo, na lista de pessoas, toca na pessoa e escolhe «Tornar administrador». A pessoa é avisada. No mesmo menu podes retirar o papel (sem aviso) ou, na tua linha, «Deixar de ser administrador», desde que fique outro. Se o último administrador sair, o membro mais antigo passa a administrador.' },
  { q: 'Como funciona o cofre do grupo?', a: 'Cada um põe vibes no cofre (de 10 a 100 000 de cada vez). Os administradores pagam ao local com o cofre ou devolvem-no: a devolução vai para quem pôs, na proporção do que cada um meteu. Quem sai do grupo não leva as vibes. Se o grupo acabar, o cofre é devolvido sozinho.' },
  { q: 'Como pago num local com vibes?', a: 'Na página do local, toca em «Pagar com vibes» (só aparece nos locais que aceitam). Escolhe o valor, confirma e recebes um recibo. O pagamento não se desfaz pela app, por isso confirma antes. Quem gere o local vê quem pagou, quanto e a nota.' },
  { q: 'O que é À tua volta?', a: 'Em Pesquisa, «À tua volta» mostra num mapa os locais, os eventos, as publicações recentes e os TxillGroups visíveis no mapa, perto de ti ou da cidade que escolheres, até à distância que puseres na barra (de 1 a 50 km), em «Onde procurar». Com a localização autorizada, abre onde estás; a cidade só fica se a localização não der. O mapa centra-se na tua posição exata só no teu ecrã: ao servidor vai arredondada (cerca de 1 km) e não fica guardada. Aparecer no mapa para a malta está desligado de origem: liga-o no mapa ou em Definições, Privacidade, «Aparecer em À tua volta» (só a partir dos 18 anos). Só apareces com a localização do telemóvel: com uma cidade escolhida, não. Só se vê a zona aproximada, e sais do mapa ao fim de 3 horas, ou logo que desligas a opção, escolhes uma cidade ou terminas a sessão. As publicações das pessoas aparecem só pela zona aproximada (cerca de 1 km), e as tuas não te aparecem aí.' },
  { q: 'Quem me pode ligar?', a: 'Escolhes tu em Definições, Mensagens e chamadas, «Quem me pode ligar»: todos, quem eu sigo, amigos mútuos (de origem) ou ninguém. Quem bloqueaste nunca te liga. Se não atenderes, fica uma chamada perdida nas notificações.' },
  { q: 'Tenho um bar ou restaurante. Como crio a página?', a: 'Em Definições, Conteúdo e o teu algoritmo, «Tenho um local». Crias a página, marcas no mapa onde fica, pões foto, morada e horário, e a equipa do Txillapp aprova-a (até lá só tu e os gestores a veem; recebes uma notificação com a decisão). Podes convidar gestores: o administrador edita tudo e o editor publica como o local. Quem segue o local vê as publicações no feed. Podes anunciar eventos e ligar «Aceitar pagamentos em vibes» para a malta pagar aí. O QR do local serve para a malta fazer check-in.' },
  { q: 'Como ponho o meu local no mapa?', a: 'Ao criar a página, ou em Gerir, em «Onde fica?»: escreve o nome ou a rua e escolhe uma sugestão. Depois podes tocar em «Ajustar no mapa» e arrastar até o alfinete ficar na porta, ou em «Usar a minha localização» se estiveres lá (a app explica antes de pedir a autorização). A pesquisa vai pelo servidor do Txillapp até ao OpenStreetMap, sem dizer quem és. O ponto que gravas é público: aparece no À tua volta e na página do local, com «Como chegar» (a não ser que desligues «Mostrar no mapa»).' },
  { q: 'Posso tirar o meu local do mapa?', a: 'Sim. Em Gerir, desliga «Mostrar no mapa» (só o dono e os administradores). O local, os eventos e as publicações feitas como o local deixam de aparecer no mapa e em perto de mim, e só quem gere a página vê o ponto. A página continua na pesquisa pelo nome e mostra a morada que escreveste.' },
  { q: 'Como ponho texto num mimo?', a: 'No editor do mimo (também ao partilhar um post como mimo), toca em «Aa» e escreve. Em cima mudas o alinhamento e o fundo (sem fundo, cheio ou suave); em baixo escolhes a cor e a letra, entre as 10 do estúdio. Toca em «Feito» para o pousar. Depois arrasta-o para o mover e, com dois dedos, faz crescer e roda (ou usa os botões que aparecem quando o escolhes). Toca no texto para o reescrever; para o apagar, larga-o no caixote ou deixa-o vazio. Cabem até 10 textos e 12 stickers por mimo. Os textos passam pelo mesmo filtro das legendas.' },
  { q: 'Posso mudar a letra de uma publicação ou da legenda do Zás?', a: 'Sim. Numa publicação só com texto (sem fotos nem vídeos), escolhe a letra na fila por baixo do texto, em «Letra da publicação»; ao editar a publicação também a podes mudar. Com fotos ou vídeos fica a letra de sempre. No Zás, depois de escreveres a legenda, aparece a fila «Letra da legenda»; o teu aparelho lembra-se da última que escolheste. A letra fica guardada com a publicação ou com o Zás e todos a veem como tu.' },
  { q: 'Quem pode repostar as minhas publicações?', a: 'Quem pode ver uma publicação tua pode repostá-la no perfil, tal como está ou com um comentário, enquanto «Deixar repostar as minhas publicações» estiver ligado (vem ligado). Numa conta privada, quem te segue também pode, e o repost só o vê quem pode ver o original, ou seja, quem te segue. Tu podes sempre repostar as tuas. Para repostar uma citação têm de deixar os dois: quem a fez e o autor da publicação citada. Quando alguém reposta uma publicação tua, recebes um aviso.' },
  { q: 'Como impeço que repostem as minhas publicações?', a: 'Em Definições, Conteúdo e o teu algoritmo, «As tuas publicações», desliga «Deixar repostar as minhas publicações». Desligado, só tu repostas as tuas publicações e o «Repostar» deixa de aparecer aos outros (também o «Repostar com comentário»). Os reposts que já existem ficam. Se a tua conta já era privada quando a opção chegou, ficou desligada: liga-a se quiseres que quem te segue possa repostar.' },
  { q: 'Como oculto uma publicação minha?', a: 'Na tua publicação (foto, carrossel, texto, tcheka, citação ou presente), toca em ⋯ e em «Ocultar publicação». Num repost teu, toca em ⋯ e em «Ocultar o repost». Não há pergunta: aparece um aviso com «Desfazer». Enquanto está oculta só tu a vês: sai do feed, do teu perfil, da pesquisa, das hashtags, dos sítios e dos locais, das tchekas e das páginas dos sons, dos reposts e das citações, dos mimos que a partilharam e das partilhas nas conversas, e quem abrir a ligação vê «Esta publicação não está disponível». Não conta nas tuas publicações e ninguém a pode brindar, comentar, oferecer vibes, repostar ou guardar, nem a podes partilhar numa conversa. Os brindes, os comentários e os presentes que já tinha ficam. Uma publicação a bombar, ou com o Bombar marcado, só se oculta quando o Bombar acabar.' },
  { q: 'Onde ficam as publicações que ocultei?', a: 'No teu perfil, no separador «Ocultas» (o olho riscado), que só tu vês e só aparece quando tens alguma oculta. Toca em «Voltar a mostrar» no quadrado, ou abre a publicação e escolhe «Voltar a mostrar» no ⋯. Volta ao mesmo sítio, com a data de sempre e com os brindes e os comentários, e ninguém é avisado outra vez. Podes ocultar e voltar a mostrar as vezes que quiseres. As ocultas entram em «Descarregar os meus dados», com a marca de ocultas, e apagam-se com a conta. A moderação do Txillapp continua a vê-las, marcadas «Oculta pelo autor». Guardamos só a data em que as ocultaste.' },
  { q: 'Como guardo um mimo na galeria?', a: 'Abre o teu mimo e, no menu, toca em «Guardar na galeria». A foto ou o vídeo vai com os stickers, os textos (na letra e no sítio em que os puseste) e a assinatura do Txillapp com o teu @. Só dá para guardar os teus mimos.' },
  { q: 'Como leio um QR que está no meu telemóvel?', a: 'Em Pesquisar (o ícone do QR), em Partilhar perfil › Ler um QR ou em Convida a tua malta, toca em «Escolher da galeria» e escolhe a imagem ou a captura de ecrã com o QR. No computador também a podes colar. Também dá para apontar a câmara a um QR noutro ecrã ou em papel. Se for um perfil, um convite, uma publicação ou um sítio do Txillapp, abre logo na app; outros endereços perguntam antes de abrir, e o texto só se mostra e copia. A imagem é lida no teu aparelho e não é enviada.' },
  { q: 'Como guardo um Zás?', a: 'Abre o teu Zás e toca em «Guardar na galeria» (também está no menu de cada Zás em «Os meus Zás»; no site há ainda «Descarregar»). Sai o Zás como na app: o cartão com a foto, a legenda na curva na letra que escolheste, a data e a hora e, por baixo, a assinatura do Txillapp (o logótipo, o teu @ e o teu selo, se o tiveres). Sai um ficheiro JPG, também quando o partilhas. Só dá para guardar os teus Zás, e só enquanto existem: os outros veem-nos 24 horas e, com «Guardar os meus Zás para o resumo semanal» ligado (vem ligado), para ti ficam 7 dias em «Os meus Zás», com a marca «Só tu». Desligado, apagam-se às 24 horas.' },
  { q: 'O que é o resumo semanal dos Zás?', a: 'Ao domingo à noite (hora de Moçambique), se tiveste 3 Zás ou mais nessa semana, juntamos os teus Zás numa imagem, como um cartaz da semana, e recebes o aviso «O teu resumo dos Zás da semana está pronto». Está no topo de «Os meus Zás» e só tu o vês até o partilhares. Podes «Partilhar nos mimos» (para os Amigos ou só para os Amigos próximos), «Guardar» na galeria ou «Partilhar» fora da app; também o podes descartar. O resumo apaga-se ao fim de uma semana. Para isto, os teus Zás ficam guardados 7 dias só para ti (os outros continuam a vê-los só 24 horas) e depois apagam-se de vez, com a foto. Só há duas exceções: um Zás com uma denúncia por decidir fica até à decisão, e, se alguém respondeu a um Zás teu, a foto fica nessa conversa. O resumo é feito de forma automática no nosso servidor, sem ninguém o ver. Não queres? Em Definições, Privacidade, «Zás», desliga «Guardar os meus Zás para o resumo semanal»: os Zás guardados que já passaram das 24 horas e o resumo por partilhar apagam-se logo, e deixa de haver resumo. O aviso desliga-se à parte, em Definições, Notificações, «Resumo dos Zás».' },
  { q: 'Como guardo uma tcheka?', a: 'Na tcheka, toca em «⋯» e em «Guardar o vídeo» (no site, «Descarregar o vídeo»), ou em Partilhar e «Guardar vídeo». Dá sempre para as tuas (num dueto, só se o autor do original também deixar). Nas de outras pessoas, só se quem publicou deixar guardar (numa conta privada ou de um menor nunca dá) e, num dueto, também o autor do original; senão, a opção não aparece. No telemóvel vai para a galeria (a app pede acesso só para a guardar lá); no site é descarregada ou abre a partilha do sistema. A primeira vez pode demorar uns segundos, enquanto o vídeo se prepara. Numa publicação com várias fotos e vídeos sai o primeiro vídeo, e num repost sai o original.' },
  { q: 'O que leva a tcheka que guardo?', a: 'O vídeo com a assinatura do Txillapp no canto (o logótipo e o @ de quem publicou) e, no fim, um cartão de 2,6 segundos com o logótipo, o @, o selo de verificado (se a conta o tiver) e txillapp.com. Numa publicação feita como um local, o cartão mostra o nome do local. Leva o som e a música como se ouvem no Txillapp, quando a música já está gravada no vídeo. Não leva a localização GPS nem outros dados escondidos do ficheiro. Quem publicou não é avisado, e o Txillapp não guarda quem guardou. Se partilhares a tcheka de outra pessoa, deixa a assinatura e não a publiques como tua.' },
  { q: 'Posso impedir que guardem as minhas tchekas?', a: 'Sim. Em Definições → Conteúdo e o teu algoritmo → «As tuas tchekas», desliga «Deixar guardar as minhas tchekas» (vem ligado). Desligado, só tu guardas as tuas tchekas, e o «Guardar o vídeo» deixa de aparecer aos outros. Numa conta privada, ou se tens menos de 18 anos (ou não indicaste a data de nascimento), ninguém além de ti as guarda, nem quem te segue. Com a opção ligada, pode guardar quem pode ver a tcheka, nunca quem tem um bloqueio contigo, e a cópia leva sempre o teu @. Vale também para os duetos feitos com as tuas tchekas: um dueto só se guarda se tu e quem o fez deixarem, e se apagares a tcheka original ninguém o guarda. Numa tcheka com o teu som, vale a escolha de quem a publicou. Ao desligar a opção, ou ao passar a conta a privada, as cópias que estão no Txillapp (das tuas tchekas e dos duetos feitos com elas) apagam-se logo; senão, cada uma apaga-se sozinha 30 dias depois de feita, ou quando eliminas a conta. As cópias que já estão no telemóvel de alguém ficam lá, mesmo que desligues a opção ou apagues a tcheka ou a conta.' },
  { q: 'Fiz um dueto. Posso guardá-lo?', a: 'Sim, se tu e o autor da tcheka original deixarem guardar, porque o dueto leva o vídeo dele. Se ele não deixar, se a conta dele for privada ou se apagar a tcheka original, ninguém guarda o dueto, nem tu. O mesmo ao contrário: o autor do original só guarda o teu dueto se tu deixares.' },
  { q: 'A música fica gravada na minha tcheka?', a: 'Sim, numa tcheka de um só vídeo: depois de publicares, o nosso servidor mistura a música (ou o som de «Usar este som») no próprio vídeo, e até ficar pronto toca por cima, como antes. Assim a música vai também na tcheka que alguém guarda. Só se gravam as músicas de licença aberta, as dos artistas de Moçambique, os sons das tchekas e os teus clipes de áudio; as outras continuam a tocar por cima. As tchekas do estúdio já trazem a música no vídeo. Se a música deixar de poder tocar (o som é retirado ou a música do artista é tirada), volta o vídeo original.' },
  { q: 'Posso fazer uma captura de ecrã de um Zás?', a: 'Dos teus, sim. Na app do Android e do iPhone, a captura do Zás de outra pessoa fica bloqueada: no Android é recusada e a gravação do ecrã sai preta, no iPhone sai em branco. Se o telemóvel detetar a captura (no iPhone e no Android 14 ou mais recente), o dono recebe a notificação «fez uma captura do teu Zás»; não fica nada na conversa. No site, o browser não deixa bloquear nem detetar. E ninguém consegue impedir que fotografem o ecrã com outra câmara.' },
  { q: 'De onde vem a música?', a: 'De um catálogo escolhido pelo Txillapp: música de licença aberta (CC0, domínio público e CC BY) das melhores das fontes públicas, arrumada por estilos (Afrobeats, Amapiano, Marrabenta, Gospel, Festa, Praia e outros), e músicas de artistas de Moçambique que autorizaram o Txillapp (estas só nos mimos e nas tchekas), sempre com o autor e a licença à vista. A pesquisa fica no nosso servidor. «Em alta no Txillapp» mostra as mais usadas na última semana, sem dizer quem as usou. Toca no X («Não gosto desta») para uma faixa deixar de te aparecer (se foi sem querer, toca logo em «Desfazer»); quando muita gente marca a mesma, ela desce para todos, e ninguém vê quem marcou. Marca as faixas de que gostas como favoritas para as teres à mão. A música de um post toca sozinha quando o post está à vista; podes silenciá-la.' },
  { q: 'Como ponho a minha música no Txillapp?', a: 'Se és artista ou editora em Moçambique, vai a Definições, Conta, «Sou artista». Pedes com o teu nome artístico, os estilos, as tuas ligações (redes e streaming) e quem tem os direitos (tu ou a editora, com uma declaração e, se quiseres, uma prova). A equipa do Txillapp confirma, avisa-te na app e o teu perfil passa a ter a etiqueta «Artista» (não é o selo de verificado). A prova só a equipa a vê e é apagada logo a seguir à decisão. Depois carregas cada música (MP3, M4A ou AAC, até 20 MB, no site txillapp.com), com o título, a capa, os estilos, o trecho a usar (o refrão, de 15 a 60 segundos) e se é explícita, e aceitas a Licença de uso de música no Txillapp: autorizas, de graça e sem exclusividade, que a malta use o trecho nos mimos e nas tchekas. A música é revista e aparece nos «Artistas de Moçambique», no seletor de música, com «♪ Título · Artista» e a ligação ao teu perfil. As músicas explícitas não aparecem a menores de 18 anos. Em «As minhas músicas» vês quantas vezes cada uma foi usada e por quantas pessoas (nunca quem), e podes retirá-la: deixa de estar disponível para novos usos, e os mimos e as tchekas que já a usam continuam. Não há pagamento pelas músicas nem pelos usos. A licença completa está nos Termos de Uso, ponto 12.' },
  { q: 'Alguém pôs uma música minha sem autorização. O que faço?', a: `Abre a música (toca no nome dela num mimo ou numa tcheka) e escolhe «Denunciar por direitos de autor», com o teu nome, um email e o que se passa. A música fica escondida logo, também nos mimos e nas tchekas que já a usam, enquanto a equipa do Txillapp analisa, e podemos contactar-te por esse email. Se te derem razão, a música sai de vez; se não, volta. O artista não fica a saber quem denunciou. Denúncias falsas podem levar à suspensão da conta. Também podes escrever para ${SUPPORT}, com o assunto «Direitos de autor».` },
  { q: 'O que preciso para publicar uma tcheka?', a: 'No estúdio das tchekas, junta pelo menos 3 fotos, ou 3 segundos de vídeo, ou 5 segundos de fotos e vídeos misturados. Tem de ter som: o do vídeo, uma música ou uma voz-off com 3 segundos ou mais (só com fotos, escolhe uma música ou grava uma voz-off). O máximo são 60 segundos. A capa escolhes tu, num instante do vídeo. Se faltar alguma coisa, o estúdio diz o quê. O estúdio está na app do telemóvel e no site txillapp.com, no browser do telemóvel ou do computador.' },
  { q: 'Como corto um clipe?', a: 'Na linha do tempo, toca no clipe e arrasta as pontas dele. Para o partir em dois, põe o cursor no sítio e toca em Dividir (no computador, a tecla S). Para mudar a ordem, segura o clipe e arrasta-o (com o rato, agarra e arrasta). Duplicar, Velocidade, Som, Encher ou Inteiro, Apagar e Substituir estão nas ações do clipe. Se te enganares, toca em Desfazer (Ctrl+Z) ou em Refazer.' },
  { q: 'A minha foto ou o meu vídeo aparece cortado. Como o mostro inteiro?', a: 'Toca no clipe na linha do tempo e escolhe como fica no ecrã (na app, no botão Encher ou Inteiro das ações do clipe; no site, em Enquadrar). «Inteiro» mostra a foto ou o vídeo todo, ao centro, com a mesma imagem desfocada e mais escura por trás a ocupar o resto do ecrã. «Encher» ocupa o ecrã todo ao alto e corta as pontas que sobram. «Auto», que vem de origem, enche o ecrã com as fotos e os vídeos ao alto e mostra inteiros os deitados e os quadrados. A escolha é de cada clipe, fica no rascunho e sai assim no vídeo final. Num dueto e numa foto com moldura de capulana não há esta escolha: no dueto cada lado enche a sua parte, e a moldura já mostra a foto inteira.' },
  { q: 'Como mantenho o som do meu vídeo?', a: 'Escolhe o clipe na linha do tempo e, em Som, deixa-o Ligado e acerta o volume: cada vídeo tem o seu. Com música, o som dos vídeos fica mais baixo; em Som, Mistura, sobe «Som dos vídeos» ou o de cada vídeo. Sem música, o som dos vídeos é o som da tcheka e passa a ser o teu «Som original».' },
  { q: 'Como escolho o trecho da música?', a: 'Em Som, Trecho, arrasta a onda até à parte que queres: vais ouvindo enquanto arrastas. A sugestão com a estrela é o refrão ou a parte mais forte, e «Do início» volta ao começo. «Ajustar ao ritmo» acerta o trecho e os cortes dos vídeos para caírem nas batidas, e em Moldes há ritmos prontos a usar. Em Mistura acertas os volumes, a entrada e a saída suaves da música e se ela baixa quando falas na voz-off.' },
  { q: 'Como gravo uma voz-off?', a: 'Em Som, Voz-off, toca em gravar: depois de uma contagem de 3 segundos a tcheka toca e falas por cima. O microfone só está ligado enquanto gravas e desliga-se quando paras, cancelas ou sais. Depois podes ouvir, regravar, apagar, mudar o volume e pôr um efeito de voz (Robô, Esquilo, Grave, Eco, Rádio ou Estádio). Na linha do tempo, arrasta a faixa da voz-off para mudar onde entra. Com 3 segundos ou mais, conta como o som da tcheka. No site, a gravação fica no teu aparelho até publicares.' },
  { q: 'O que é a Montagem mágica?', a: 'Em Clipes, toca em «Montagem mágica» (com pelo menos 2 fotos ou vídeos) e escolhe uma onda: a app escolhe os melhores momentos, enquadra as pessoas, ordena e corta ao ritmo da música. «Outra versão» faz outra, e «Afinar» passa-a para a linha do tempo para mexeres à vontade. A análise das fotos, dos vídeos e da música é feita no teu aparelho: nada sai dele nem fica guardado, e não reconhece nem identifica caras.' },
  { q: 'Onde ficam os rascunhos?', a: 'Nada se guarda sozinho. Ao sair do estúdio com o «x», escolhes «Guardar rascunho» (fica só neste aparelho, na app ou no browser, nunca na tua conta) ou «Apagar» (sai de vez). Quando voltas ao estúdio aparece «Continuar o rascunho?», com a lista dos outros, até 10 (os mais antigos saem). O rascunho é apagado quando publicas a tcheka, e também o podes apagar na lista: toca no caixote e depois em «Apagar». Terminar a sessão apaga-os todos neste aparelho, e também limpar os dados do browser ou desinstalar a app.' },
  { q: 'Que efeitos, texto e stickers posso pôr?', a: 'Em Efeitos: filtros, ajustes de cor, transições entre clipes, rampas de velocidade, inverter e congelar um frame, e a Capulana, com panos desenhados por código pelo Txillapp para transições, molduras, faixas e letras. Em Texto escolhes a letra, as cores e a animação; em Stickers há emojis, os stickers do Txillapp, menções, local e hora (os GIFs do GIPHY ficam só nas conversas e nos comentários). Arrasta, roda e escala no ecrã, e na linha do tempo mudas quando cada um aparece e sai.' },
  { q: 'O que é o «Som original» de uma tcheka?', a: 'Quando publicas uma tcheka com o som do próprio vídeo, sem escolher música, o Txillapp tira o áudio (até 60 segundos) e faz dele um som: «Som original · @tu». Toca no nome do som ou no disco de uma tcheka para abrir a página dele, com as tchekas que o usam, e em «Usar este som» para fazeres a tua com ele. Em «Sons em alta», no Explorar, vês os mais usados da semana, só com números, nunca quem os usou.' },
  { q: 'Como impeço que usem o meu som?', a: 'Em Definições, Conteúdo e o teu algoritmo, «As tuas tchekas», desliga «Deixar usar o meu som». Vem ligado de origem. Desligado, ninguém faz tchekas novas com os teus sons, mas as que já os usam continuam a tocá-los. Numa conta privada, abaixo dos 18 anos ou sem data de nascimento na conta, só tu os podes usar. Se apagares a tcheka de onde o som saiu, o som perde a página e os usos novos; os antigos continuam. Num dueto, o teu som vai com o teu vídeo, mesmo com esta opção desligada.' },
  { q: 'Como tiro o meu som de todo o lado?', a: 'Abre a página do teu som, ou Definições, Conteúdo e o teu algoritmo, «Os meus sons», e toca em «Retirar o som». O som deixa de existir e de tocar em todo o lado: as tchekas que o usam ficam sem som e mostram «Som retirado pelo autor» (quem as fez não é avisado uma a uma), e o áudio guardado à parte é apagado. A tua tcheka de onde o som saiu fica como está. Dá também depois de apagares essa tcheka. Não dá para desfazer.' },
  { q: 'Um som tem música protegida. O que faço?', a: 'Abre a página do som, toca em «Denunciar este som» e escolhe «Tem música protegida». O som fica logo suspenso para tchekas novas enquanto a equipa do Txillapp analisa. Se a equipa te der razão, o som é retirado e deixa de tocar também nas tchekas que já o usavam, que mostram «Som retirado por direitos de autor». Quem publicou não fica a saber quem denunciou. Se publicas uma tcheka com o som do vídeo, garante que tens o direito de usar esse áudio.' },
  { q: 'O que são os duetos e as respostas com tcheka?', a: 'Num dueto gravas o teu vídeo lado a lado com a tcheka de outra pessoa: o vídeo e o som dela ficam gravados no teu, com «Dueto com @…» e a ligação ao original. Começa em Remix, «Fazer dueto». Para responder com tcheka, toca em «Responder com tcheka» debaixo de um comentário: o comentário aparece por cima do teu vídeo, onde o puseres, e leva até ele. A câmara e o microfone só são usados enquanto gravas. Um bloqueio, em qualquer sentido, impede os dois.' },
  { q: 'Como impeço duetos e respostas com as minhas tchekas?', a: 'Em Definições, Conteúdo e o teu algoritmo, «As tuas tchekas», desliga «Deixar fazer duetos e respostas com as minhas tchekas». Vem ligado nas contas públicas e numa conta privada nunca vale. Desligado, ninguém faz duetos novos com as tuas tchekas nem responde com tcheka aos teus comentários; os que já existem ficam, também se apagares a tua tcheka. O aviso «Duetos e respostas» desliga-se à parte, em Definições, Notificações.' },
  { q: 'Fizeram um dueto com a minha tcheka e não quero. Como o tiro?', a: 'Abre o dueto, toca em «⋯» e em «Retirar o dueto». O teu vídeo e o teu som estão gravados nele, por isso não precisas de passar pela equipa: o dueto deixa de aparecer para todos e quem o fez recebe o aviso de que pediste para o retirar. Não dá para desfazer. Isto é só para os duetos (lado a lado); uma resposta com tcheka só mostra o texto do comentário e, se violar as regras, denuncia-se como qualquer publicação. Se eliminares a conta, os duetos com as tuas tchekas ficam escondidos sozinhos.' },
  { q: 'O Txillapp suspendeu ou retirou o meu som. O que posso fazer?', a: 'Recebes um aviso do Txillapp com o motivo, por exemplo «Música protegida denunciada». Suspenso, o som continua a tocar nas tchekas que já o usam, mas ninguém o usa em tchekas novas até a equipa decidir. Retirado, deixa de tocar em todo o lado. Se o som é teu ou tens autorização para usar essa música, escreve para suporte@txillapp.com com o assunto «Contestar som» e explica porquê. Se a equipa rever a decisão, o som volta a tocar. Nunca sabes quem denunciou, e estes avisos não se desligam.' },
  { q: 'Como funcionam os brindes?', a: 'Tocas em «Brindar» num post, numa Tcheka ou num comentário para mostrar que gostaste. Nos comentários dos mimos e de uma Txillada, também com dois toques no comentário ou no balão que flutua (os dois toques só põem o brinde; para o tirar, usa o botão). É grátis e a pessoa é avisada (quem brinda o que é seu não gera aviso), menos nos comentários de uma Txillada: aí não há aviso e a contagem só se vê na sala, enquanto está a decorrer. Numa publicação ou Tcheka aparece «Brindado por @fulano e outras N pessoas», com até 3 fotos: primeiro os teus amigos próximos, depois quem segues, depois os mais recentes; os teus amigos próximos que brindaram (ou, se nenhum brindou, até 3 pessoas que segues) aparecem também por cima da foto ou da Tcheka, com uma caneca (só tu os vês assim, e ninguém fica a saber quem são os teus amigos próximos). Os nomes seguem a escolha do autor em Definições, Privacidade, «Quem vê quem brindou» (todos, os seguidores dele ou só ele), e nunca aparecem contas com um bloqueio contigo, desativadas ou privadas que não segues; quando não se podem ver, aparece só o número. Quem vê o comentário vê quantos brindes tem, não quem brindou. Os brindes juntam-se num só aviso por publicação ou comentário, como «ana, rui e 3 outros brindaram a tua publicação», e no telemóvel o aviso chega de vez em quando, com a contagem, para não ser chato. Tirar o brinde não apaga o aviso, mas deixa de contar. Para não receberes estes avisos, desliga «Brindes e reações» em Definições, Notificações.' },
  { q: 'Como funciona o convite?', a: 'Em Convites tens o teu código, a ligação e um cartão para partilhar, feito no teu telemóvel com o teu nome, a foto, o código e até 4 itens públicos da tua geleira (nunca bebidas com álcool se tiveres menos de 18 anos). Quem abre a ligação vê o teu nome, o @, a foto e esses itens, mesmo sem conta. Quando alguém entra com o teu código, recebes um aviso. Se já tens o email confirmado e mais de 3 dias de conta, a pessoa recebe 50 vibes quando a conta dela fica ativa (confirma o email, publica algo ou segue 3 pessoas e volta ao Txillapp noutro dia); tu recebes 50 quando ela continua por cá mais 7 dias. Contas repetidas, no mesmo aparelho ou com o mesmo email disfarçado, contas automáticas e registos em massa não contam, e uma conta em revisão pela equipa só conta depois da revisão. As vibes não valem dinheiro.' },
  { q: 'O que quer dizer «Bombado · Patrocinado»?', a: 'É um destaque pago por um local perto de ti, com as vibes do local, para mostrar um evento ou uma publicação. Leva sempre essa etiqueta e o nome do local. Só aparece a maiores de 18 anos, no máximo 3 vezes por dia o mesmo destaque, e cerca de 1 em cada 11 publicações do feed. Para os escolher usamos a tua zona aproximada (cerca de 1 km) do À tua volta ou a cidade escolhida, sem a guardar. O local só vê totais, nunca quem viu. Se não quiseres ver os destaques de um local, toca em «Não mostrar destaques deste local».' },
  { q: 'Como bombo o meu local?', a: 'Em Gerir, Bombar (só o dono e os administradores, com o local aprovado e no mapa). Escolhe o evento ou a publicação feita como o local, o pacote (1, 3 ou 7 dias) e o raio (1 a 10 km), e paga com as vibes da carteira do local. Se parares, voltam à carteira os dias inteiros que faltam, ou tudo se ainda não começou. A equipa do Txillapp pode suspender um destaque que viole as regras, com ou sem devolução. No relatório vês as vezes mostrado, as pessoas, os toques, os interessados e os check-ins, nunca quem foi.' },
  { q: 'Como ofereço vibes a alguém?', a: 'Só podes oferecer vibes a quem segues. No post, toca em «Oferecer»; no perfil, no ícone do presente. O presente vai inteiro para quem o recebe. Podes deixá-lo em silêncio, privado ou publicá-lo para toda a gente ver.' },
  { q: 'O que é a geleira?', a: 'A tua vitrine de gostos: ambientes, bebidas, comidas e sítios. Edita-a em Editar perfil. O nível da geleira sobe com o que vives com a malta (vê «Como sobe o nível da geleira?»). Quem a vê pode brindá-la; por omissão só tu vês quem brindou, mas em Editar perfil podes ligar «Mostrar quem brindou a minha geleira».' },
  { q: 'Como sobe o nível da geleira?', a: 'O nível mede o que vives com a malta nos últimos 90 dias, não o que pões na geleira. Contam as geladas pagas e confirmadas (3 pontos a quem paga, 2 a quem recebe, também pelo «Bora!»), os brindes de amigos que te seguem e que segues (1 por pessoa, uma vez a cada 30 dias), os check-ins com o QR de um local (2 por local, uma vez por semana em cada um), as rodadas fechadas no TxillGroup (1 por entrar, 2 por pagar) e, um pouco, os gostos da geleira (variedade e notas, no máximo 8 pontos). O álcool não conta: uma gelada de refresco vale o mesmo. As vibes da carteira também não contam. A mesma pessoa vale no máximo 6 pontos por semana, e contas bloqueadas, suspensas ou eliminadas não contam. «Maningue abastecida» pede 40 pontos com pelo menos 2 pessoas; «Paulada garantida» e o topo pedem mais pontos, mais pessoas diferentes e semanas seguidas com atividade. Se deixares de sair, o nível desce devagar, no máximo um por semana. Na tua geleira, toca em «Como subo?» para veres de onde vêm os teus pontos e o que falta; só tu vês esse detalhe, quem visita vê o nome do nível e a barra.' },
  { q: 'Como partilho a minha geleira?', a: 'Abre a tua geleira no perfil (ou o editor da geleira) e toca em «Partilhar a minha geleira». Sai uma publicação com o frigorífico e os teus gostos tal como estão nesse momento, com uma legenda se quiseres; se mudares a geleira depois, o post fica igual e leva a ligação para a geleira de agora. Quem vê o post pode brindar o post todo ou tocar num gosto para lhe brindar, e esses brindes contam também na geleira do teu perfil (cada pessoa brinda uma vez a cada gosto, seja no post ou no perfil). Se apagares o post, os brindes ficam. As bebidas com álcool só aparecem a quem tem 18 anos ou mais, e o post segue as regras normais: conta privada, bloqueios e quem pode ver as tuas publicações. Com a geleira vazia não dá para partilhar.' },
  { q: 'O que é o «Paga-me uma»?', a: 'É pedir a um amigo que te pague uma bebida, ao jeito da sexta. Toca numa bebida da tua geleira (ou da de um amigo) e em «Paga-me uma», ou toca no ícone do «Paga-me uma» no perfil da pessoa (a mão com a caneca), ou no + da conversa e em «Pede uma gelada». Quem recebe responde «Bora!», «Hoje não» ou «Fica a dever». Não há dinheiro nem vibes nisto: é palavra entre amigos.' },
  { q: 'Mando o pedido no chat ou publico?', a: 'Escolhes tu. «Mandar no chat» manda um cartão a cada amigo, com as regras normais das mensagens (bloqueios e quem te pode escrever). «Publicar» faz uma publicação com a malta identificada: só quem foi identificado responde e os outros brindam e comentam. Na publicação podes juntar uma música em «Adicionar um hit», como nas outras publicações (as músicas dos artistas de Moçambique só vão em mimos e tchekas); no chat não há hit. Em público só pedes a quem te segue e tu segues de volta, e que deixa ser mencionado. Quem foi identificado pode tirar a identificação, e o pedido fecha para ele.' },
  { q: 'Há limites nos pedidos?', a: 'Sim: até 10 pedidos por dia e até 3 por dia ao mesmo amigo (no chat e em publicações, juntos). Um pedido é sempre uma bebida: nada de desafios de quantidade.' },
  { q: 'E se tiver menos de 18 anos?', a: 'Abaixo dos 18 (ou sem data de nascimento na conta) não aparecem bebidas com álcool: o pedido é de um refresco ou um sumo, com tudo igual. Se um adulto pedir uma bebida com álcool a um menor, o pedido passa sozinho a refresco.' },
  { q: 'O que é o livro das geladas?', a: 'É onde fica quem deve a quem: as dívidas do «Fica a dever», das rodadas e as que crias com «Fico a dever-te uma». Quem deve toca em «Já paguei» (pode juntar uma foto e o local onde foi: primeiro os que estão perto, ou pelo nome) e só fica paga quando a outra pessoa confirma. O local não é um check-in: é a etiqueta «no Bar X». Se estiveres mesmo lá (até 150 m) ou um de vocês fizer check-in com o QR do local na mesma hora, leva o selo «✓ estiveram lá». Quem recebe pode também «Perdoar». Uma gelada paga e confirmada conta para o nível da geleira dos dois (3 pontos a quem pagou, 2 a quem recebeu); os pedidos sozinhos não contam.' },
  { q: 'Quem vê o meu livro das geladas?', a: 'Por omissão, cada dívida só a veem as duas pessoas. Em Definições, Conteúdo, podes ligar «Mostrar o livro das geladas a quem vê a geleira»: aí quem pode ver a tua geleira vê também o teu livro. As fotos e o local do «Já paguei» só os veem os dois (a não ser que publiquem o momento).' },
  { q: 'O que é a sexta da gelada?', a: 'À sexta, por volta das 17h, mandamos no máximo um aviso: quem ainda te deve uma, ou um lembrete para pedires à malta. Abaixo dos 18 o aviso fala de refrescos. Desliga em Definições, Notificações, «Sexta da gelada». Bebe com moderação 🙌' },
  { q: 'Como funciona a rodada num TxillGroup?', a: 'No grupo, toca no + e em «Rodada». Cada um escolhe «Eu entro» com a bebida, e alguém diz «Esta pago eu»; o cartão mostra quem paga e quem bebe e sugere quem paga a próxima, para não ser sempre o mesmo. Ao fechar, quem pagou pode pôr no livro o que cada um lhe ficou a dever.' },
  { q: 'O que é a visualização única?', a: 'Fotos, vídeos, voz e mensagens que só se abrem uma vez e depois desaparecem do chat. Quem recebe pode, mesmo assim, fotografar o ecrã.' },
  { q: 'Como denuncio alguma coisa?', a: 'Usa o menu (os três pontos), segura a mensagem ou o comentário, ou toca na bandeira, e escolhe Denunciar. Dá para publicações, comentários, mimos e os comentários deles, Zás, Txilladas e os comentários delas (toca no comentário), mensagens, perfis e locais. A pessoa não sabe que foste tu, e o que denunciaste deixa de te aparecer. A moderação quer decidir em menos de 24 horas e pode remover o conteúdo e suspender a conta. Também podes escrever para suporte@txillapp.com.' },
  { q: 'Como bloqueio alguém?', a: 'No perfil da pessoa, toca nos três pontos e escolhe Bloquear. Vês e desbloqueias quem bloqueaste em Definições, Privacidade, «Contas bloqueadas».' },
  { q: 'Como pedir o selo de verificado?', a: 'Em Definições, Conta, «Pedir o selo de verificado». A conta tem de cumprir alguns requisitos e depois enviamos o pedido com um documento e uma selfie, que a moderação revê. Os documentos são apagados quando há decisão.' },
  { q: 'O que querem dizer as cores do selo?', a: 'O selo vermelho é dado pelo Txillapp: quer dizer que a conta foi verificada por mérito ou porque o pedido de verificação foi aceite. A conta oficial do Txillapp também tem o selo vermelho. O selo azul é o da verificação paga, quando existir.' },
  { q: 'Como cancelo a subscrição do selo azul?', a: 'A subscrição é da loja onde a fizeste e renova sozinha até a cancelares. No iPhone: Definições, o teu nome, Subscrições, Txillapp. No Android: Google Play, o teu perfil, Pagamentos e subscrições, Subscrições, Txillapp. Também chegas lá em Definições, Conta, Selo azul, «Gerir subscrição». Cancela pelo menos 24 horas antes do fim do período; o selo azul fica até ao fim do período já pago. Os reembolsos são pedidos à Apple ou à Google.' },
  { q: 'Quem vê quando estou online?', a: 'Só quem também mostra a presença. Em Definições, Privacidade, «Mostrar quando estou online» desliga isso (e também deixas de ver os outros).' },
  { q: 'Que estatísticas de uso a app envia?', a: 'Com «Ajudar a melhorar o Txillapp» ligado (Definições, Privacidade, Contactos e dados), a app envia-nos, só a nós: as aberturas, os ecrãs vistos (só o nome do ecrã), o tempo de arranque, os erros (uma mensagem curta e limpa de dados pessoais) e as ações que fazes (publicar, comentar, brindar, seguir, repostar, partilhar, enviar mensagens, pesquisar, ver mimos, ligar as notificações), com a plataforma e a versão da app. Nunca o conteúdo nem a posição. Sem internet, até 200 registos esperam no aparelho (no máximo 3 dias). Desligado, ou com «não rastrear» no browser, não enviamos nada e o que estava à espera é apagado.' },
  { q: 'Porque me aparece o aviso das notificações desligadas?', a: 'Porque as notificações estão desligadas neste aparelho e podes perder mensagens e chamadas. Aparece no máximo uma vez por dia e, de cada vez que tocas em «Agora não», espera mais (3, 7, 14 e depois 30 dias). Em Definições, Notificações, há também uma faixa para as ligar. As horas destes avisos ficam só no teu aparelho.' },
  { q: 'Porque recebi um lembrete do Txillapp?', a: 'Porque não abres o Txillapp há 3 dias ou mais. Chega por notificação ou, se nenhuma chegar, por email. No máximo um por semana, só entre as 9h e as 20h, e param ao fim de 90 dias sem abrir. Dizem só o que há de novo para ti, com números e o primeiro nome de quem segues (mensagens por ler, publicações, mimos, brindes), nunca o que te escreveram. Não vão a menores de 18. Para não os receberes, desliga «Lembretes quando não passo por cá» em Definições, Notificações, ou toca em «Deixar de receber estes lembretes» no email, sem entrares na conta.' },
  { q: 'Como mudo a privacidade da conta?', a: 'Em Definições, Privacidade: perfil público ou privado, quem comenta e quem te menciona. Quem te envia mensagens e quem te pode ligar está em Definições, Mensagens e chamadas. Também podes procurar qualquer opção em «Procurar nas definições».' },
  { q: 'Esqueci-me da senha. E agora?', a: 'No ecrã de entrada, toca em «Esqueceste a senha?». Enviamos-te um email para criares uma nova.' },
  { q: 'Como elimino a minha conta?', a: 'Em Definições, Conta, «Eliminar conta». Isto não se desfaz: apagamos o perfil, as publicações, as conversas, as chamadas e o resto dos teus dados. Podes descarregar os teus dados antes, no mesmo ecrã.' },
  { q: 'Posso apagar a conta sem a app?', a: 'Sim, em txillapp.com/apagar-conta. Escreves o email da conta e mandamos-te uma ligação que vale 1 hora. A conta só é apagada quando confirmas na página que essa ligação abre.' },
];

/** Ajuda: perguntas frequentes e contacto (igual à do site). */
export default function Help() {
  // A pergunta aberta guarda-se pelo texto (não pela posição na lista): ao procurar, não abre outra pergunta qualquer.
  const [open, setOpen] = useState<string | null>(null);
  const [term, setTerm] = useState('');
  const purchases = usePurchases();
  // Sem acentos nem maiúsculas, como em "Procurar nas definições": "notificacoes" encontra "notificações".
  const words = normalize(term).split(/\s+/).filter(Boolean);
  const list = helpFaqFor(purchases, FAQ).filter((f) => { const hay = normalize(`${f.q} ${f.a}`); return words.every((w) => hay.includes(w)); });
  const subject = encodeURIComponent('Problema no Txillapp');
  const body = encodeURIComponent(`\n\n---\nVersão: ${Constants.expoConfig?.version ?? ''}\nAparelho: ${Platform.OS} ${Platform.Version}`);
  return (
    <StackPage title="Ajuda">
      <ScrollView contentContainerStyle={{ paddingBottom: 40 }} keyboardShouldPersistTaps="handled">
        <View style={{ paddingHorizontal: 16, paddingTop: 16 }}>
          <SearchField value={term} onChangeText={setTerm} placeholder="Procurar na ajuda" />
        </View>
        <Group title="Perguntas frequentes">
          {list.length === 0 ? <Text style={st.none}>Nada com essa palavra. Fala connosco, em baixo.</Text> : null}
          {list.map((f) => (
            <View key={f.q}>
              <Pressable onPress={() => setOpen(open === f.q ? null : f.q)} accessibilityRole="button" accessibilityState={{ expanded: open === f.q }} aria-expanded={open === f.q} style={({ pressed }) => [st.q, pressed && { backgroundColor: colors.zinc50 }]}>
                <Text style={st.qText}>{f.q}</Text>
                <View style={{ transform: [{ rotate: open === f.q ? '90deg' : '0deg' }] }}><Icon name="chevron-right" size={18} color={colors.zinc400} /></View>
              </Pressable>
              {open === f.q ? <Text style={st.a}>{f.a}</Text> : null}
            </View>
          ))}
        </Group>
        <Group title="Fala connosco">
          <Line icon="mail" label="Contactar o suporte" value={SUPPORT} href={`mailto:${SUPPORT}`} />
          <Line icon="alert" label="Reportar um problema" value="Já leva a versão e o aparelho" href={`mailto:${SUPPORT}?subject=${subject}&body=${body}`} />
          <Line icon="shield" label="Segurança e privacidade" to="/privacy" />
          <Line icon="music" label="Direitos de autor" value={SUPPORT} href={`mailto:${SUPPORT}?subject=${encodeURIComponent('Direitos de autor')}`} />
        </Group>
      </ScrollView>
    </StackPage>
  );
}

const st = StyleSheet.create({
  none: { paddingHorizontal: 16, paddingVertical: 24, textAlign: 'center', color: colors.zinc500, fontSize: 16 },
  q: { minHeight: 56, flexDirection: 'row', alignItems: 'center', gap: 12, paddingHorizontal: 16, paddingVertical: 12 },
  qText: { flex: 1, fontSize: 16, fontWeight: '600', color: colors.zinc900 },
  a: { paddingHorizontal: 16, paddingBottom: 16, fontSize: 15, lineHeight: 21, color: colors.zinc700 },
});
